import { createContext, type ReactElement, type ReactNode, use } from "react";

export type IconDefaults = {
	/** Classes an unstyled `Icon` in this subtree adopts, e.g. `size-4.5`. */
	className: string;
	/** Theme colour token, e.g. `primary-foreground`. */
	color: string;
};

const IconDefaultsContext = createContext<IconDefaults | null>(null);

/**
 * Supplies the size and colour that unstyled `Icon`s in this subtree adopt.
 *
 * This is what lets an icon be *composed into* a component rather than passed
 * as a prop: `<Button><Icon icon={IconPlus} /><Button.Label>Add</Button.Label></Button>`
 * sizes and tints the icon for the button's variant, with no `startIcon` prop
 * and no colour repeated at the call site. An explicit `size` or `color` on the
 * icon still wins.
 */
export function IconDefaultsProvider({ value, children }: { value: IconDefaults; children: ReactNode }): ReactElement {
	return <IconDefaultsContext value={value}>{children}</IconDefaultsContext>;
}
IconDefaultsProvider.displayName = "DelacourUI.Icon.DefaultsProvider";

/** Icon defaults from the nearest provider, or null outside one. */
export function useIconDefaults(): IconDefaults | null {
	return use(IconDefaultsContext);
}

import type { ComponentType, ReactElement } from "react";
import type { SvgProps } from "react-native-svg";
import { withUniwind } from "uniwind";
import { useThemeColor } from "@registry/hooks/use-theme-color";
import { useIconDefaults } from "./icon.context";
import { ICON_FALLBACK_COLOR, type IconSize, isIconSize, resolveIconSizeClass } from "./icon.variants";

export type IconComponent = ComponentType<SvgProps & { size?: number | string }>;

export type IconProps = Omit<SvgProps, "color" | "width" | "height"> & {
	/** An icon component from `@registry/icons/central`. */
	icon: IconComponent;
	/** A named size, or an edge length in points. A number beats `className`. */
	size?: IconSize | number;
	/**
	 * A theme colour token (`foreground`, `muted-foreground`, …) or a CSS
	 * variable name. Defaults to the enclosing component's icon colour.
	 */
	color?: string;
	/** A `size-*` utility. Beats a named `size`, loses to a numeric one. */
	className?: string;
};

type IconGlyphProps = Omit<SvgProps, "color" | "width" | "height"> & {
	glyph: IconComponent;
	size?: number | string;
	color?: string;
	className?: string;
};

/**
 * Renders the glyph and drops the className that sized it.
 *
 * This one indirection is what keeps the whole Central Icons set to a *single*
 * `withUniwind` wrapper: the wrapper goes on this component, which takes the
 * glyph as data, rather than on each of the two thousand icon components.
 * AGENTS.md rule 7 caps a component at one wrapper in one file — this is it.
 *
 * The className must not reach the glyph. `withManualUniwind` spreads the
 * original props straight through, and `CentralIconBase` would forward a stray
 * `className` onto the native SVG view, where nothing interprets it.
 */
function IconGlyph({ glyph: Glyph, className: _sizedBy, ...props }: IconGlyphProps): ReactElement {
	return <Glyph {...props} />;
}
IconGlyph.displayName = "DelacourUI.Icon.Glyph";

/**
 * Turns a `size-*` class into the glyph's `size` **prop**.
 *
 * A className cannot size an SVG through a style: `CentralIconBase` spreads its
 * props onto `<Svg>` before its own `width`/`height`, and `Svg.render` pushes
 * the width/height-derived styles on last, beating anything a className set.
 *
 * `withManualUniwind` reads `props.className`, compiles it, and writes
 * `styles.width` to `size` — but skips the mapping entirely when `size` is
 * already defined. That skip *is* the precedence rule: a numeric `size` from the
 * caller wins and the class is ignored.
 *
 * Created once at module scope. Calling `withUniwind` inside a render would mint
 * a new component type every frame and remount the icon.
 */
const StyledIconGlyph = withUniwind(IconGlyph, {
	size: { fromClassName: "className", styleProperty: "width" },
});

/**
 * Renders a Central Icon at a theme-aware size and colour.
 *
 * An icon's size is a class and an icon's colour is a token — a class cannot
 * express a literal like `#EC4899` or reach an SVG paint prop, so colour is
 * resolved through the active theme instead. See AGENTS.md.
 *
 * Both fall back to the nearest {@link IconDefaultsProvider}, so an icon
 * composed into a Button matches that button's size and variant without being
 * told to. An explicit `size` or `color` still wins.
 */
export function Icon({ icon, size, color, className, ...props }: IconProps): ReactElement {
	const defaults = useIconDefaults();
	const resolvedColor = useThemeColor(color ?? defaults?.color ?? ICON_FALLBACK_COLOR);

	return (
		<StyledIconGlyph
			className={resolveIconSizeClass({ className, inherited: defaults?.className, size })}
			color={resolvedColor}
			glyph={icon}
			size={isIconSize(size) ? undefined : size}
			{...props}
		/>
	);
}
Icon.displayName = "DelacourUI.Icon";

import { cn } from "@registry/lib/cn";
import { tv } from "@registry/lib/tv";

export const ICON_SIZES = ["xs", "sm", "md", "lg", "xl", "2xl"] as const;

export type IconSize = (typeof ICON_SIZES)[number];

/**
 * Edge length for each named icon size, as a token class rather than a number.
 *
 * The steps come from the `--spacing-icon-*` scale in `tokens.css`, which
 * `Spinner` names identically — so `size="md"` is the same edge length in both
 * and one can replace the other without the layout moving. A control's own size
 * axis indexes into the same scale rather than restating a number.
 *
 * A className can never size a Central Icon through a style. `CentralIconBase`
 * spreads its props onto `<Svg>` *before* its own `width`/`height`, and
 * `Svg.render` then pushes the width/height-derived styles onto the root last,
 * where they beat anything a className contributed. So the size has to arrive as
 * the `size` **prop** — `Icon` runs this class through `withUniwind` to recover
 * the width and hands that to the glyph. See `icon.tsx`.
 *
 * No `defaultVariants` on purpose. The fallback has to *lose* to an inherited
 * class, and a default here would emit from inside this same call, ahead of it
 * in the merge. {@link resolveIconSizeClass} orders the sources instead.
 *
 * Free of React Native imports so it stays unit-testable — `bun test` cannot
 * parse React Native's Flow-typed source. See AGENTS.md.
 */
export const iconVariants = tv({
	variants: {
		size: {
			xs: "size-icon-xs",
			sm: "size-icon-sm",
			md: "size-icon-md",
			lg: "size-icon-lg",
			xl: "size-icon-xl",
			"2xl": "size-icon-2xl",
		},
	},
});

/** Edge length used with no `size`, no `className` and nothing to inherit — 20pt. */
export const ICON_FALLBACK_SIZE_CLASS = "size-icon-lg";

/** Theme token used with no `color` prop and nothing to inherit from. */
export const ICON_FALLBACK_COLOR = "foreground";

/** Whether a size is one of the named steps rather than an edge length in points. */
export function isIconSize(size: IconSize | number | undefined): size is IconSize {
	return typeof size === "string";
}

/**
 * The class chain that sizes an icon, weakest source first: the fallback, the
 * enclosing component's class, this icon's named size, then the caller's own
 * className. `cn` resolves the conflicts, so the last `size-*` wins.
 *
 * A numeric `size` is deliberately absent. It is not a class — it goes straight
 * to the glyph's prop, and uniwind then skips its mapping because that prop is
 * already defined. That skip *is* the precedence rule.
 *
 * Note for callers overriding through `className`: use `size-*`, not `w-*` with
 * `h-*`. tailwind-merge conflicts `size` into `w`/`h` but not the reverse, so a
 * trailing `w-6` will not clear a leading `size-5`.
 *
 * Pure, so the whole ladder is reachable from `bun test`. See AGENTS.md.
 */
export function resolveIconSizeClass({
	size,
	inherited,
	className,
}: {
	size?: IconSize | number;
	inherited?: string;
	className?: string;
}): string {
	return cn(ICON_FALLBACK_SIZE_CLASS, inherited, isIconSize(size) ? iconVariants({ size }) : undefined, className);
}

export { Icon, type IconComponent, type IconProps } from "./icon";
export { type IconDefaults, IconDefaultsProvider, useIconDefaults } from "./icon.context";
export {
	ICON_FALLBACK_COLOR,
	ICON_FALLBACK_SIZE_CLASS,
	ICON_SIZES,
	type IconSize,
	iconVariants,
	isIconSize,
	resolveIconSizeClass,
} from "./icon.variants";
